      "本体を中表に二つ折りにし、長辺（斜めの辺）を縫い合わせて筒にします。",
      "伸びる生地の場合は、伸縮ステッチか細かいジグザグを使ってください。直線縫いだと、着脱のときに糸が切れます。",
      "縫い代は片側に倒してアイロンで押さえます。"
