    "<strong>裁断する</strong><br>本体を表布・裏布 各2枚、マチを表布・裏布 各1本、持ち手を2本裁ちます。マチが長いので、布の長さ方向に取ってください。",
    "<strong>接着芯を貼る</strong><br>表布の本体とマチの裏面に厚手の接着芯を貼ります。自立させたいので省かないでください。",
