      "持ち手の端から、本体の高さの3分の1くらいまで縦にステッチを2本入れ、上端は四角に×を描くように縫って補強します。",
      "この「縦に長く縫い付ける」形が、重い荷物を入れても抜けない秘訣です。上端だけを縫うと必ず外れます。",
      "本体が平らなうちに済ませるのが鉄則。組み立ててからでは押さえが届きません。"
