  desc:"リモコンポケットの作り方。ソファのひじ掛けに掛けるだけで、リモコンや雑誌が定位置に。反対側の垂れがおもりになってずれません。カタガミで型紙を実寸印刷できます。",
  keywords:"リモコンポケット,ソファ,収納,作り方,型紙,整理,インテリア,ハンドメイド",
